				return diffFlags{}, nil, errors.New("--head requires a value")
			}
			if err := validateRevision("--head", rest[i]); err != nil {
				return diffFlags{}, nil, err
			}
			parsed.head = rest[i]
		default:
			if strings.HasPrefix(rest[i], "-") && rest[i] != "-" {
				unknown = append(unknown, rest[i])
				continue
