+type TestRef struct { ID string `yaml:"id" json:"id"`; Acceptance string `yaml:"acceptance" json:"acceptance"`; Selector struct { Name string `yaml:"name" json:"name"` } `yaml:"selector" json:"selector"` }
+type Spec struct {
+	Version int `yaml:"version" json:"version"`
+	ID string `yaml:"id" json:"id"`
+	Title string `yaml:"title" json:"title"`
+	Intent string `yaml:"intent" json:"intent"`
+	Status string `yaml:"status,omitempty" json:"status,omitempty"`
+	Requirements []Requirement `yaml:"requirements" json:"requirements"`
+	Acceptance []Acceptance `yaml:"acceptance" json:"acceptance"`
+	Anchors []AnchorRef `yaml:"anchors" json:"anchors"`
+	Tests []TestRef `yaml:"tests" json:"tests"`
+	Path string `yaml:"-" json:"path"`
+}
+
+type Baseline struct { SignatureHash string `yaml:"signature_hash" json:"signature_hash"`; ContainerID string `yaml:"container_id,omitempty" json:"container_id,omitempty"`; BodyHash string `yaml:"body_hash" json:"body_hash"`; FileBlob string `yaml:"file_blob,omitempty" json:"file_blob,omitempty"` }
+type Selector struct { QualifiedName string `yaml:"qualified_name" json:"qualified_name"`; Kind string `yaml:"kind" json:"kind"`; File string `yaml:"file" json:"file"` }
+type Binding struct { ID string `yaml:"id" json:"id"`; SymbolID string `yaml:"symbol_id" json:"symbol_id"`; Selector Selector `yaml:"selector" json:"selector"`; Baseline Baseline `yaml:"baseline" json:"baseline"` }
+type BindingFile struct { Version int `yaml:"version" json:"version"`; Anchors []Binding `yaml:"anchors" json:"anchors"`; Path string `yaml:"-" json:"path"` }
+type Set struct { Policy Policy `json:"policy"`; Specs []Spec `json:"specifications"`; Bindings []Binding `json:"bindings"`; Diagnostics []string `json:"diagnostics,omitempty"`; Digest string `json:"digest"` }
+
+func Init(repo string) error {
+	root := filepath.Join(repo, Root)
+	for _, part := range []string{"specs", "anchors"} { if err := os.MkdirAll(filepath.Join(root, part), 0o755); err != nil { return err } }
+	path := filepath.Join(root, "intent.yaml")
+	if _, err := os.Stat(path); err == nil { return fmt.Errorf("%s already exists", filepath.ToSlash(filepath.Join(Root, "intent.yaml"))) } else if !errors.Is(err, os.ErrNotExist) { return err }
+	return os.WriteFile(path, []byte("version: 1\nspecs_root: specs\nanchors_root: anchors\n"), 0o644)
+}
+
+func Load(repo string) (Set, error) {
+	set := Set{Policy: Policy{Version: 1, SpecsRoot: "specs", AnchorsRoot: "anchors"}}
