+	if err := decodeFile(policyPath, &set.Policy); err != nil { return set, fmt.Errorf("read policy: %w", err) }
+	if set.Policy.Version != 1 || !safeRelative(set.Policy.SpecsRoot) || !safeRelative(set.Policy.AnchorsRoot) { return set, errors.New("intent policy must use version 1 and relative roots") }
+	if err := loadYAMLFiles(filepath.Join(repo, Root, set.Policy.SpecsRoot), func(path string) error { var spec Spec; if err := decodeFile(path, &spec); err != nil { return err }; spec.Path = rel(repo, path); if err := validateSpec(&spec); err != nil { return fmt.Errorf("%s: %w", spec.Path, err) }; set.Specs = append(set.Specs, spec); return nil }); err != nil { return set, err }
+	if err := loadYAMLFiles(filepath.Join(repo, Root, set.Policy.AnchorsRoot), func(path string) error { var bindings BindingFile; if err := decodeFile(path, &bindings); err != nil { return err }; if bindings.Version != 1 { return fmt.Errorf("%s: unsupported binding version", rel(repo,path)) }; for _, binding := range bindings.Anchors { if binding.ID == "" || binding.SymbolID == "" { return fmt.Errorf("%s: binding requires id and symbol_id", rel(repo,path)) }; set.Bindings = append(set.Bindings, binding) }; return nil }); err != nil { return set, err }
+	if err := validateSet(&set); err != nil { return set, err }
+	sort.Slice(set.Specs, func(i,j int) bool { return set.Specs[i].ID < set.Specs[j].ID }); sort.Slice(set.Bindings, func(i,j int) bool { return set.Bindings[i].ID < set.Bindings[j].ID })
