+const gpsSchemaVersion = "1.0"
+
+func runSpec(ctx context.Context, opts Options, args []string) error {
+	if len(args) == 0 { return errors.New("spec requires init, list, show, or validate") }
+	verb, flags, err := gpsFlags(args[1:]); if err != nil { return err }
+	repo, err := resolveRepo(ctx, opts.Env, flags.repo); if err != nil { return err }
