+	case "list": return gpsEncode(opts, flags.format, map[string]any{"schema_version": gpsSchemaVersion, "intent_digest": set.Digest, "specifications": set.Specs})
+	case "show":
+		if flags.id == "" { return errors.New("spec show requires --id") }; for _, spec := range set.Specs { if spec.ID == flags.id { return gpsEncode(opts, flags.format, spec) } }; return fmt.Errorf("specification %q not found", flags.id)
+	case "validate": return gpsEncode(opts, flags.format, map[string]any{"schema_version": gpsSchemaVersion, "valid": true, "intent_digest": set.Digest, "specifications": len(set.Specs)})
+	default: return fmt.Errorf("unknown spec command %q", args[0])
+	}
+}
+
+func runAnchor(ctx context.Context, opts Options, args []string) error {
+	if len(args) == 0 { return errors.New("anchor requires bind, list, or resolve") }
+	verb, flags, err := gpsFlags(args[1:]); _ = verb; if err != nil { return err }
+	repo, err := resolveRepo(ctx, opts.Env, flags.repo); if err != nil { return err }
+	set, err := intent.Load(repo); if err != nil { return err }
+	if args[0] == "list" { return gpsEncode(opts, flags.format, map[string]any{"schema_version": gpsSchemaVersion, "intent_digest": set.Digest, "anchors": set.Bindings}) }
+	if args[0] == "bind" {
+		if flags.id == "" || flags.symbol == "" { return errors.New("anchor bind requires --id and --symbol") }
+		snapshot, err := gpsSnapshot(ctx, opts, repo); if err != nil { return err }
+		matches := matchingSymbols(snapshot.Symbols, flags.symbol, flags.file)
+		if len(matches) == 0 { return fmt.Errorf("symbol %q not found", flags.symbol) }; if len(matches) > 1 { return fmt.Errorf("symbol %q is ambiguous; pass --file", flags.symbol) }
+		s := matches[0]
+		return intent.SaveBinding(repo, intent.Binding{ID: flags.id, SymbolID: s.ID, Selector: intent.Selector{QualifiedName: s.QualifiedName, Kind: s.Kind, File: s.FilePath}, Baseline: intent.Baseline{SignatureHash: intent.Hash(s.Signature), ContainerID: s.ContainerID, BodyHash: s.BodyHash}}, flags.update)
+	}
+	if args[0] == "resolve" {
+		if flags.id == "" { return errors.New("anchor resolve requires --id") }
+		snapshot, err := gpsSnapshot(ctx, opts, repo); if err != nil { return err }
+		for _, binding := range set.Bindings { if binding.ID == flags.id { return gpsEncode(opts, flags.format, resolveBinding(binding, snapshot.Symbols)) } }; return fmt.Errorf("anchor %q not found", flags.id)
+	}
+	return fmt.Errorf("unknown anchor command %q", args[0])
+}
+
+func runGPSContext(ctx context.Context, opts Options, args []string) error {
+	_, flags, err := gpsFlags(args); if err != nil { return err }; if flags.query == "" { return errors.New("context requires --query") }
+	repo, err := resolveRepo(ctx, opts.Env, flags.repo); if err != nil { return err }; set, err := intent.Load(repo); if err != nil { return err }
+	response := map[string]any{"schema_version": gpsSchemaVersion, "request": flags.query, "intent_digest": set.Digest, "status": "complete", "requirements": matchingRequirements(set, flags.query), "symbols": []any{}, "gaps": []string{}, "budget": map[string]any{"maximum_bytes": flags.maxBytes, "rendered_bytes": 0, "omitted": []string{}}}
