+	findings := make([]map[string]any, 0)
+	for _, spec := range set.Specs { for _, anchor := range spec.Anchors { found := false; for _, binding := range set.Bindings { if binding.ID == anchor.ID { found = true; state:=resolveBinding(binding,snapshot.Symbols); if state["state"] != "VALID" { findings=append(findings,map[string]any{"id":"GPS-ANCHOR-"+state["state"].(string),"severity":"warning","subject":anchor.ID,"message":state["state"]}) } }; if !found { findings=append(findings,map[string]any{"id":"GPS-ANCHOR-UNBOUND","severity":"warning","subject":anchor.ID,"message":"declared anchor has no reviewed binding"}) } }; for _, acceptance := range spec.Acceptance { mapped:=false; for _, test:=range spec.Tests {if test.Acceptance==acceptance.ID {mapped=true}}; if !mapped {findings=append(findings,map[string]any{"id":"GPS-MAPPING-MISSING","severity":"warning","subject":acceptance.ID,"message":"acceptance criterion has no declared test"})} } }
+	disposition := "PASS"; if len(findings)>0 {disposition="REVIEW_REQUIRED"}; return gpsEncode(opts, flags.format, map[string]any{"schema_version":gpsSchemaVersion,"intent_digest":set.Digest,"disposition":disposition,"findings":findings})
+}
+
+type gpsOptions struct { repo, format, id, symbol, file, query string; update bool; maxBytes int }
+func gpsFlags(args []string) (string, gpsOptions, error) { flags:=gpsOptions{format:"json",maxBytes:12000}; var rest []string; for i:=0;i<len(args);i++ { a:=args[i]; next:=func()(string,error){i++;if i>=len(args){return "",fmt.Errorf("%s requires a value",a)};return args[i],nil}; switch a { case "--repo":v,e:=next();if e!=nil{return "",flags,e};flags.repo=v; case "--format":v,e:=next();if e!=nil{return "",flags,e};flags.format=v; case "--id":v,e:=next();if e!=nil{return "",flags,e};flags.id=v; case "--symbol":v,e:=next();if e!=nil{return "",flags,e};flags.symbol=v; case "--file":v,e:=next();if e!=nil{return "",flags,e};flags.file=v; case "--query":v,e:=next();if e!=nil{return "",flags,e};flags.query=v; case "--max-context-bytes":v,e:=next();if e!=nil{return "",flags,e};if _,e:=fmt.Sscan(v,&flags.maxBytes);e!=nil||flags.maxBytes<1{return "",flags,errors.New("--max-context-bytes requires a positive integer")}; case "--update":flags.update=true; case "--json":flags.format="json"; default:rest=append(rest,a) } }; if len(rest)>0{return "",flags,fmt.Errorf("unexpected arguments: %s",strings.Join(rest," "))};if flags.format!="json"&&flags.format!="text"{return "",flags,errors.New("--format must be json or text")};return "",flags,nil }
+func gpsSnapshot(ctx context.Context,opts Options,repo string)(sem.ProviderSnapshot,error){ snapshot,_,err:=sem.LoadOrBuildProviderSnapshot(ctx,repo,opts.Version,sem.ProviderSnapshotOptions{NoNetwork:true,Worktree:true,Profile:sem.ProfileFull},"",true);return snapshot,err }
+func matchingSymbols(symbols []sem.SymbolRecord, name,file string) []sem.SymbolRecord { var out []sem.SymbolRecord;for _,s:=range symbols{if (s.QualifiedName==name||s.Name==name||s.ID==name)&&(file==""||s.FilePath==file){out=append(out,s)}};return out }
