+func matchingRequirements(set intent.Set, query string) []map[string]string { words:=strings.Fields(strings.ToLower(query));var out []map[string]string;for _,s:=range set.Specs{for _,r:=range s.Requirements{text:=strings.ToLower(s.Title+" "+s.Intent+" "+r.ID+" "+r.Description);for _,word:=range words{if strings.Contains(text,word){out=append(out,map[string]string{"specification":s.ID,"id":r.ID,"description":r.Description,"reason":"lexical_match"});break}}}};sort.Slice(out,func(i,j int)bool{return out[i]["id"]<out[j]["id"]});return out }
+func gpsEncode(opts Options,format string,value any)error{if format=="json"{encoder:=json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout));encoder.SetEscapeHTML(false);return encoder.Encode(value)};data,err:=json.MarshalIndent(value,"","  ");if err==nil{_,err=fmt.Fprintln(opts.Stdout,string(data))};return err}
